51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
65	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
69	
70	    /**
71	     * Common address abbreviations expanded to their full form during address normalization.
72	     * Matching is performed per whitespace-separated token on the upper-cased value.
73	     */
74	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
75	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        LocalDate today = LocalDate.now();
126	        long createdToday = this.clinicService.findAllOwners().stream()
127	            .filter(existing -> today.equals(existing.getRegistrationDate()))
128	            .count();
129	        if (createdToday >= 100) {
130	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
131	        }
132	        String address = normalizeAddress(owner.getAddress());
133	        if (address == null || address.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        owner.setAddress(address);
137	        String telephone = toE164(owner.getTelephone());
138	        if (telephone == null) {
139	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
140	        }
141	        owner.setTelephone(telephone);
142	        if (owner.getRegistrationDate() == null) {
143	            owner.setRegistrationDate(LocalDate.now());
144	        }
145	        if (owner.getEmail() != null) {
146	            String email = normalizeEmail(owner.getEmail());
147	            if (!EMAIL_PATTERN.matcher(email).matches()) {
148	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
149	            }
150	            owner.setEmail(email);
151	        }
152	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
153	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
154	        if (telephoneInUse) {
155	            return new ResponseEntity<>(HttpStatus.CONFLICT);
156	        }
157	        String cityKey = householdKey(owner.getCity());
158	        long cityCount = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> existing.getCity() != null
160	                && cityKey.equals(householdKey(existing.getCity())))
161	            .count();
162	        if (cityCount >= 50) {
163	            return new ResponseEntity<>(HttpStatus.CONFLICT);
164	        }
165	        String lastNameKey = householdKey(owner.getLastName());
166	        String addressKey = householdKey(owner.getAddress());
167	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
168	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
169	                && addressKey.equals(householdKey(existing.getAddress())))
170	            .toList();
171	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
172	            String householdId = householdMembers.stream()
173	                .map(Owner::getHouseholdId)
174	                .filter(Objects::nonNull)
175	                .findFirst()
176	                .orElseGet(() -> householdId(owner));
177	            owner.setHouseholdId(householdId);
178	            for (Owner member : householdMembers) {
179	                if (member.getHouseholdId() == null) {
180	                    member.setHouseholdId(householdId);
181	                    this.clinicService.saveOwner(member);
182	                }
183	            }
184	        } else if (!householdMembers.isEmpty()) {
185	            return new ResponseEntity<>(HttpStatus.CONFLICT);
186	        }
187	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
188	        String firstNameKey = householdKey(owner.getFirstName());
189	        String namesakeLastNameKey = householdKey(owner.getLastName());
190	        long namesakeCount = this.clinicService.findAllOwners().stream()
191	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
192	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
193	            .count();
194	        owner.setNamesakeCount((int) namesakeCount);
195	        this.clinicService.saveOwner(owner);
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
