202	    /**
203	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
204	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
205	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
206	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
207	     *
208	     * @param telephone the raw telephone value (may be {@code null})
209	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
210	     *         a valid E.164 number
211	     */
212	    private String toE164(String telephone) {
213	        if (telephone == null) {
214	            return null;
215	        }
216	        String trimmed = telephone.trim();
217	        boolean hasCountryCode = trimmed.startsWith("+");
218	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
219	        if (hasCountryCode) {
220	            cleaned = cleaned.substring(1);
221	        }
222	        if (!cleaned.matches("[0-9]+")) {
223	            return null;
224	        }
225	        String digits;
226	        if (hasCountryCode) {
227	            digits = cleaned;
228	        } else {
229	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
230	            digits = "61" + national;
231	        }
232	        if (digits.length() < 8 || digits.length() > 15) {
233	            return null;
234	        }
235	        return "+" + digits;
236	    }
