238	    /**
239	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
240	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
241	     *
242	     * @param email the raw email value (must not be {@code null})
243	     * @return the trimmed, lower-cased email
244	     */
245	    private String normalizeEmail(String email) {
246	        return email.trim().toLowerCase(Locale.ROOT);
247	    }
