249	    /**
250	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
251	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
252	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
253	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
254	     * normalized form, and every household comparison uses it.
255	     *
256	     * @param address the raw address value (may be {@code null})
257	     * @return the normalized address, or {@code null} if the input was {@code null}
258	     */
259	    private String normalizeAddress(String address) {
260	        if (address == null) {
261	            return null;
262	        }
263	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
264	        if (collapsed.isEmpty()) {
265	            return collapsed;
266	        }
267	        String[] tokens = collapsed.split(" ");
268	        StringBuilder sb = new StringBuilder(collapsed.length());
269	        for (int i = 0; i < tokens.length; i++) {
270	            if (i > 0) {
271	                sb.append(' ');
272	            }
273	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
274	        }
275	        return sb.toString();
276	    }
