278	    /**
279	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
280	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
281	     * so that owners are compared case-insensitively with collapsed whitespace.
282	     *
283	     * @param value the raw value (must not be {@code null})
284	     * @return the normalized comparison key
285	     */
286	    private String householdKey(String value) {
287	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
288	    }
289	
290	    /**
291	     * Derives a stable, shared household identifier for the owner's household. The value is a
292	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
293	     * every owner in the same household derives the identical identifier of the form
294	     * {@code 'HH-<12 upper-case hex>'}.
295	     *
296	     * @param owner the owner whose household identifier is derived
297	     * @return the stable household identifier
298	     */
299	    private String householdId(Owner owner) {
300	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
301	        try {
302	            byte[] digest = MessageDigest.getInstance("SHA-256")
303	                .digest(key.getBytes(StandardCharsets.UTF_8));
304	            StringBuilder sb = new StringBuilder(digest.length * 2);
305	            for (byte b : digest) {
306	                sb.append(String.format("%02x", b));
307	            }
308	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
309	        }
310	        catch (java.security.NoSuchAlgorithmException e) {
311	            throw new IllegalStateException("SHA-256 not available", e);
312	        }
313	    }
