315	    /**
316	     * Builds the customer code for a newly registered owner in the form
317	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
318	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
319	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
320	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
321	     *
322	     * @param city     the owner's city
323	     * @param lastName the owner's last name
324	     * @return the assigned customer code
325	     */
326	    private String nextCustomerCode(String city, String lastName) {
327	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
328	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
329	        String cityKey = householdKey(city);
330	        int sequence = (int) this.clinicService.findAllOwners().stream()
331	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
332	            .count() + 1;
333	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
334	    }
